arguments.command:
cd /app && P="psql -h /var/lib/postgresql/sockets -U consul -d consul_development -tA"; 
echo "--- related_contents ---"; $P -c "select id, parent_relationable_type, parent_relationable_id, child_relationable_type, child_relationable_id from related_contents where parent_relationable_type ilike '%proposal%' or child_relationable_type ilike '%proposal%'";
echo "--- polls related ---"; $P -c "select id, name, related_type, related_id from polls where related_type is not null";
echo "--- votation_types ---"; $P -c "select id, vote_type from votation_types limit 5" 2>&1 | head; 
echo "--- dashboard_actions ---"; $P -c "select * from dashboard_actions";
echo "--- dashboard_executed_actions ---"; $P -c "select * from dashboard_executed_actions";
echo "--- proposal_notifications ---"; $P -c "select id, proposal_id, author_id, title, moderated, hidden_at from proposal_notifications";
echo "--- map_locations / poll_questions with proposal_id ---"; $P -c "select count(*) from map_locations where proposal_id is not null"; $P -c "select count(*) from poll_questions where proposal_id is not null";
echo "--- notifications w/ proposal related ---"; $P -c "select id, notifiable_type, notifiable_id, user_id, action from notifications where notifiable_type in ('ProposalNotification','Comment')";
echo "--- sdg relations ---"; $P -c "select relatable_type, related_sdg_type, count(*) from sdg_relations group by 1,2"; $P -c "select 'sdg_reviews', relatable_type, count(*) from sdg_reviews group by 2" 2>&1 | head -5
echo "--- images/documents/milestones/map/relations types ---"; for t in images documents milestones map_locations relations embedded_videos; do $P -c "select '$t', count(*) from information_schema.tables where table_name='$t'"; done

