// 01. Dashboard global
// --------------------

.proposal-dashboard {
  @include admin-layout;
}

.proposal-title {
  display: inline-block;

  .label {
    display: inline-block;
    margin-left: calc($line-height / 2);
    vertical-align: top;
  }
}

.dashboard-proposals-stats {
  border: 2px solid $highlight;
  border-radius: rem-calc(6);
  margin-bottom: $line-height;
  padding: calc($line-height / 2);
  text-align: center;

  @include breakpoint(medium only) {
    .change-behaviour {
      float: left;
      margin-top: calc($line-height / 2);
      padding: $line-height;
      width: 100%;
    }
  }

  .counter-divider {
    @include breakpoint(medium) {
      border-left: 2px solid $highlight;
    }

    @include breakpoint(large) {
      border-right: 2px solid $highlight;
    }
  }

  .counter-value {
    font-size: rem-calc(20);
    font-weight: bold;
  }

  .counter-label {
    color: $text-medium;
    font-weight: bold;
  }

  .progress {
    background: #f0efea;
    border-radius: rem-calc(6);
    height: calc($line-height / 2);
  }

  .progress-meter {
    background: #ffad33;
    border-bottom-right-radius: rem-calc(3);
    border-top-right-radius: rem-calc(3);
  }

  .next-goal-progress {
    font-size: $small-font-size;
    font-weight: bold;
    text-align: right;
  }
}

.title {
  border-bottom: 1px solid $border;
  margin: $line-height 0;
}

.dashboard-related-content {

  .related-content {
    border-top: 0;

    .margin-bottom {
      margin-bottom: 0;
    }
  }
}

// 02. Actions
// -----------

.action {
  margin-top: $line-height;

  .action-content {
    display: inline-block;
    margin-left: calc($line-height / 4);
    max-width: 90%;
    word-break: break-all;

    h4 {
      display: inline-block;
    }

    .label {
      margin-left: calc($line-height / 2);
    }

    a {
      display: block;
    }

    h4,
    p {
      margin-bottom: 0;
    }

    p {
      font-size: $small-font-size;
    }

    button {
      @include link;
    }
  }

  form {
    display: inline;
    vertical-align: top;

    button {
      font-size: 1.5em;
    }
  }

  .checked-link {
    @include has-fa-icon(check, solid);
    color: $color-success;
  }

  .unchecked-link {
    @include has-fa-icon(square, regular);
    color: $dark-gray;
  }
}

.proposed-actions {
  button {
    @include link;
  }
}

// 04. Goals
// ---------

.next-goal {
  border-left: 2px solid $border;
  margin-left: $line-height;
  margin-top: rem-calc(-24);
  padding-left: $line-height;
  padding-top: $line-height;
  position: relative;

  &::before {
    background: $body-background;
    border: 1px solid $border;
    border-radius: rem-calc(36);
    content: "\77";
    font-family: "icons";
    font-size: rem-calc(24);
    height: rem-calc(36);
    left: -18px;
    padding: 0 rem-calc(6) rem-calc(6);
    position: absolute;
    top: 18px;
    width: rem-calc(36);
  }

  .help-text {
    color: $text-medium;
    display: block;
    padding-top: calc($line-height / 4);
  }
}

.goal-supports,
.goal-resource,
.goal-days {
  margin-bottom: $line-height;
  padding-left: $line-height * 1.5;
  position: relative;

  &::before {
    font-family: "icons";
    font-size: rem-calc(24);
    left: 6px;
    position: absolute;
    top: -6px;
  }
}

.goal-supports {

  &::before {
    content: "\77";
  }
}

.goal-resource {

  &::before {
    content: "\74";
  }
}

.goal-days {

  &::before {
    content: "\67";
  }
}

.goals-section {
  button {
    @include link;
  }
}

// 05. Sidebar
// -----------

.dashboard-sidebar {
  background: #fbfbfb;
  border-right: 1px solid $border;

  [class^="icon-"] {
    display: inline-block;
    font-size: rem-calc(24);
    line-height: $line-height;
    padding: calc($line-height / 2) calc($line-height / 4);
    padding-left: 0;
    vertical-align: middle;
  }

  ul {

    li {
      line-height: $line-height * 2;
      padding-left: $line-height;
    }

    &.resources {
      border-left: 1px solid $border;
      margin-left: calc($line-height / 2);
    }
  }

  a {
    color: inherit;
  }

  .is-active {
    @include brand-color;
    position: relative;

    &::before {
      background: linear-gradient(to right, rgba(231, 236, 240, 1) 0%, rgba(251, 251, 251, 1) 90%);
      border-left: 4px solid;
      content: "";
      height: rem-calc(48);
      left: 0;
      padding-left: rem-calc(20);
      position: absolute;
      width: rem-calc(24);
    }

    a {
      @include brand-color;
    }

    [class^="icon-"] {
      @include brand-color;
    }
  }

  .has-tip {
    border-bottom: 0;
    cursor: auto;
    font-weight: normal;
  }

  .submenu-active {
    border-bottom: 2px solid;

    .has-tip {
      @include brand-color;
      font-weight: bold;
    }
  }
}

// 06. Com",
