}

.option-fields {
  background: #fbfbfb;
  border: 1px solid $border;
  margin-bottom: $line-height;
  padding: $line-height;
}

.community-poll {
  border-bottom: 1px solid $border;
  margin-bottom: $line-height;
  padding-bottom: calc($line-height / 2);
}

// 09. Email preview
// -----------------

.dashboard-mail-preview {

  max-width: rem-calc(600);

  .mail-header {
    @include background-with-text-contrast($pdf-primary);
    padding: $line-height * 2;

    img {
      max-width: rem-calc(40);
      vertical-align: top;
    }

    h1 {
      font-size: rem-calc(60);
    }

    h2 {
      margin-top: $line-height;
    }
  }

  .margin-bottom {
    img {
      box-shadow: -16px 61px 49px -19px rgba(0, 0, 0, 0.1);
      width: 100%;
    }
  }

  .mail-body {
    color: $text-medium;
    padding: $line-height * 2;
    text-align: left;

    .button {
      background: #064c86;
      box-shadow: -4px 18px 45px -19px rgba(0, 0, 0, 0.75);
      margin-bottom: $line-height * 2;
      margin-top: $line-height;
    }

    img {
      margin-top: $line-height;
      max-width: rem-calc(120);
    }

    p {
      font-size: rem-calc(24);
      line-height: rem-calc(30);
    }
  }
}

// 10. Poster preview
// ------------------

.dashboard-poster-preview,
.dashboard-poster-pdf {
  .poster-header {
    @include background-with-text-contrast($pdf-primary);

    h1 {
      text-align: left;
    }
  }

  .proposal-image {
    margin: 0 auto;
    position: relative;

    &::before {
      background: $pdf-secondary;
      content: "";
      position: absolute;
    }

    .overflow-image {
      background-position: center;
      background-repeat: no-repeat;
      background-size: cover;
      overflow: hidden;
      position: relative;
    }
  }

  .proposal-code {
    text-align: center;
  }

  .poster-content {
    margin: 0 auto;
    max-width: 90%;

    h2 {
      color: $text-medium;
      text-align: left;
    }

    h3 {
      color: $pdf-primary;
      display: inline;
    }

    .poster-footer {
      border-left: 2px solid $border;
      color: $text-medium;
    }
  }
}

.dashboard-poster-preview {

  .preview-width {
    width: rem-calc(661);
  }

  .poster-header {
    height: rem-calc(600);
    padding: $line-height * 2 $line-height;

    h1 {
      font-size: rem-calc(60);
      line-height: rem-calc(80);

      img {
        max-width: rem-calc(50);
      }
    }

    p {
      font-size: rem-calc(18);
      margin: 0 auto;
    }

    .intro {
      margin: $line-height * 2 auto;
      max-width: 60%;
      text-align: justify;
    }
  }

  .proposal-image {
    margin: 0 auto;
    max-width: 90%;
    position: relative;

    .overflow-image {
      height: 400px;
    }

    &::before {
      height: rem-calc(120);
      left: -30px;
      top: -20px;
      width: rem-calc(120);
    }

    img {
      box-shadow: 0 30px 60px rgba(0, 0, 0, 0.25);
      margin-top: rem-calc(10);
      position: relative;
      width: 100%;
    }

    h2 {
      margin: $line-height 0;
    }
  }

  .poster-content {

    img {
      max-width: rem-calc(40);
      vertical-align: top;
    }

    h2 {
      font-size: rem-calc(28);
      margin: $line-height 0;
    }

    h3 {
      font-size: rem-calc(45);
      margin-bottom: $line-height * 2;
    }
  }

  .poster-footer {
    font-size: rem-calc(19);
    margin-top: rem-calc(50);
    padding-left: rem-calc(40);
    width: 75%;
  }
}

// 11. Poster PDF
// --------------

.dashboard-poster-pdf {

  .poster-header {
    font-weight: normal;
    height: 60cm;
    padding: 5cm;

    h1 {
      font-size: 6cm;
      font-weight: bold;
      line-height: rem-calc(250);

      img {
        max-width: rem-calc(150);
      }
    }

    p {
      font-size: rem-calc(80);
      line-height: rem-calc(100);

      &.intro {
        margin: rem-calc(160) auto;
        max-width: 70%;
        text-align: justify;
      }

      &.proposal-code {
        font-size: 1.7cm;
      }
    }
  }

  .proposal-image {
    margin: 0 auto;
    max-width: 90%;
    position: relative;

    &::before {
      height: rem-calc(420);
      left: rem-calc(-130);
      top: rem-calc(-130);
      width: rem-calc(420);
    }

    .overflow-image {
      height: 37cm;
    }

    h2 {
      margin: $line-height 0;
    }
  }

  .poster-content {
    img {
      height: 3cm;
      vertical-align: top;
      width: 3cm;
    }

    h2 {
      font-size: 3cm;
      margin: $line-height 0;
    }

    h3 {
      font-size: 4.7cm;
      line-height: 5.5cm;
      margin-top: $line-height;
      max-width: 80%;
    }
  }

  .poster-footer {
    display: block;
    margin-left: 10cm;
    margin-top: 2cm;
    max-width: 75%;
    padding-left: 4cm;
  }
}
